mapper.sql:
FROM order_return_check c JOIN rental_order o ON o.id=c.rental_order_id

  AND c.check_status=#{warnings.status}
  AND c.factory_id=#{warnings.factoryId}
  AND (LOCATE(#{warnings.keyword},o.order_no)>0 OR EXISTS(SELECT 1 FROM rental_order_item i
    WHERE i.rental_order_id=o.id AND LOCATE(#{warnings.keyword},i.prop_name_snapshot)>0))
  AND c.auto_close_at>=#{warnings.fromDate} AND c.auto_close_at<DATE_ADD(#{warnings.toDate},INTERVAL 1 DAY)
